export const DICT = { zh, tw, en, ja, ko, es, fr, de, ru, pt, vi, th, id, ar, hi };

export function getLang() {
  const saved = localStorage.getItem('sa-lang');
  if (saved && DICT[saved]) return saved;
  const nav = (navigator.language || 'en').toLowerCase();
  if (nav.startsWith('zh-tw') || nav.startsWith('zh-hk')) return 'tw';
  if (nav.startsWith('zh')) return 'zh';
  const base = nav.split('-')[0];
  return DICT[base] ? base : 'en';
}

export function makeT(lang) {
  const dict = DICT[lang] || en;
  return (key, vars) => {
    let s = dict[key] ?? en[key] ?? key;
    // replaceAll + a function replacer (v0.15.2, audit FE-P2-7):
    // every occurrence is substituted (the server-side srvT
    // already used replaceAll — the two ends now agree), and a
    // value containing $&, $' etc. can no longer bite the
    // template through String.replace's pattern semantics.
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll('{' + k + '}', () => String(v));
    return s;
  };
}
